Given the root of a Binary Search Tree and a value key, find if key is present in the BST or not.Note: The key may or may not be present in the BST.Input: key = 7 Output: trueExplanation: 7 is present in the BST.Input: key = 14 Output: falseExplanation: 14 is not present in the BST.Try It YourselfHow to search a value in Binary Search Tree:Let's say we want to search for the number key, We start at the root. Then:We compare the value to be searched with the value of the root. If it's equal we are done with the search.If it's smaller we know that we need to go to the left subtree.If it's greater we search in the right subtree. Repeat the above step till no more traversal is possibleIf at any iteration, key is found, return True. If the node is null, return False.Illustration of searching a key in BST:See the illustration below for a better understanding:Searching in Binary Search Tree using Recursion:
            C++

    #include <iostream>
using namespace std;

// Node structure
class Node {
public:
    int data;
    Node* left;
    Node* right;

    Node(int item) {
        data = item;
        left = right = nullptr;
    }
};

bool search(Node* root, int key) {

    // root is null -> return false
    if (root == nullptr) return false;

    // if root has key -> return true
    if (root->data == key) return true;

    if (key > root->data) 
        return search(root->right, key);

    else
        return search(root->left, key);
}

int main() {
    // Creating BST
    //    6
    //   / \
    //  2   8
    //     / \
    //    7   9
    Node* root = new Node(6);
    root->left = new Node(2);
    root->right = new Node(8);
    root->right->left = new Node(7);
    root->right->right = new Node(9);

    int key = 7;

    // Searching for key in BST
    cout << search(root, key) << endl;
}


