            C++

    #include <iostream>
using namespace std;

// Node structure
class Node {
public:
    int data;
    Node* left;
    Node* right;

    Node(int item) {
        data = item;
        left = right = nullptr;
    }
};

bool search(Node* root, int key) {
    bool present = false;

    // iterative traversal
    while (root != nullptr) {
        if (root->data == key) {
            present = true;
            break;
        } 
        else if (key > root->data)
            root = root->right;
        else
            root = root->left;
    }
    return present;
}

